        mov     al, [mojoin__headerGood__ret]
        xor     ah, ah                      ; bool -> u16
        mov     [mojoin__joinOne__good], al ; narrowed to bool
.L210:
        jmp     .L209
.L211:
; ---- if ( n == 1 ) {
        mov     ax, [mojoin__joinOne__n]
        cmp     ax, 1
        je      .L215                       ; unsigned ==
        jmp     .L213
.L215:
; ---- if ( targetLen == 0 ) {
        mov     ax, [mojoin__targetLen]
        test    ax, ax
        jne     .L216                       ; unsigned ==
; ---- for ( u16 i = 0; i < chunkNameRoom; i++ ) {
        mov     word [mojoin__joinOne__i], 0
.L219:
        mov     ax, [mojoin__joinOne__i]
        cmp     ax, 12
        jae     .L221                       ; unsigned <
; ---- targetPath[i] = wantName[i]
        mov     ax, [mojoin__joinOne__i]
        mov     bx, ax
        mov     al, [mojoin__wantName + bx]
        mov     bx, [mojoin__joinOne__i]
        mov     [mojoin__targetPath + bx], al
.L220:
        inc     word [mojoin__joinOne__i]
        jmp     .L219
.L221:
; ---- targetPath[chunkNameRoom] = 0
        mov     byte [mojoin__targetPath + 12], 0
.L216:
; ---- target = fileCreate( addr( targetPath ) )
        mov     ax, mojoin__targetPath      ; link-time constant
        mov     [fileCreate__at], ax
        call    fileCreate
        mov     ax, [fileCreate__ret]
        mov     [mojoin__target], ax
; ---- if ( fileFailed() ) refuse( addr( sNotMade ) )
        call    fileFailed
        mov     al, [fileFailed__ret]
        xor     ah, ah                      ; bool -> u16
        test    ax, ax
        jz      .L223
        mov     ax, sNotMade                ; link-time constant
        mov     [mojoin__refuse__why], ax
        call    mojoin__refuse
.L223:
.L213:
; ---- takePayload( h )
        mov     ax, [mojoin__joinOne__h]
        mov     [mojoin__takePayload__h], ax
        call    mojoin__takePayload
; ---- fileClose( h )
        mov     ax, [mojoin__joinOne__h]
        mov     [fileClose__handle], ax
        call    fileClose
; ---- joined++
        inc     word [mojoin__joined]
; ---- space()
        call    space
; ---- space()
        call    space
; ---- putChunkPath()
        call    mojoin__putChunkPath
; ---- putStr( addr( sOk ) )
        mov     ax, sOk                     ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int16:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x16
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        ret

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pushf
        pop     ax
        and     al, 1                       ; carry is bit 0
        mov     [_cf], al
        ret

